import numpy as np
from scipy.optimize import minimize
import math

def solve():
    def objective(vars):
        x, y, z = vars
        return -(x * y**3 + y * z**3 + z * x**3)

    def constraint(vars):
        x, y, z = vars
        return x**2 + y**2 + z**2 - 3

    cons = {'type': 'eq', 'fun': constraint}
    sqrt3 = math.sqrt(3)

    start_points = []
    # Deterministic starting points
    for i in [-1, 0, 1]:
        for j in [-1, 0, 1]:
            for k in [-1, 0, 1]:
                if i == 0 and j == 0 and k == 0:
                    continue
                start_points.append([i, j, k])

    # Add more random points
    np.random.seed(42)
    for _ in range(100):
        vec = np.random.randn(3)
        vec = vec / np.linalg.norm(vec) * sqrt3
        start_points.append(vec.tolist())

    found_solutions = []
    for sp in start_points:
        res = minimize(objective, sp, constraints=cons, tol=1e-9)
        if res.success:
            x, y, z = res.x
            val = x * y**3 + y * z**3 + z * x**3
            if abs(val - 3) < 1e-6:
                # Check if it's a new solution
                is_new = True
                for sx, sy, sz in found_solutions:
                    if np.allclose([x, y, z], [sx, sy, sz], atol=1e-5):
                        is_new = False
                        break
                if is_new:
                    found_solutions.append((x, y, z))

    print(f"Number of solutions found: {len(found_solutions)}")
    for sol in found_solutions:
        print(sol)

solve()

